const j = $input.item.json;
const remote_jid = j.remote_jid || 'sem-id';
const created_at = j.created_at || new Date().toISOString();
const from_me = (typeof j.from_me === 'boolean') ? j.from_me : false;
const media_url = j.media_url || null;
let extracted = '';
if (typeof j.text === 'string') extracted = j.text;
else if (Array.isArray(j.text)) extracted = j.text.join('\n');
else if (j.text) extracted = JSON.stringify(j.text);
extracted = (extracted || '').toString().trim();
if (!extracted || extracted.length < 20) extracted = '⚠️ Não foi possível extrair texto do PDF.';
const MAX_CHARS = 12000;
if (extracted.length > MAX_CHARS) extracted = extracted.slice(0, MAX_CHARS) + '\n[TRUNCADO]';
return [{ json: { processed_type: 'documento', processed_content: `📄 Conteúdo do PDF:\n${extracted}`, media_url, created_at, remote_jid, from_me, role_label: from_me ? 'ADVOGADO' : 'CLIENTE' } }];

const json = $input.item.json;
const markdown = json.output || json.text || json.message?.content || json.content || json.response || json.data || '⚠️ ERRO: resumo não encontrado.';
let remote_jid = 'desconhecido';
try { remote_jid = $('Webhook Resumo').first().json.body.remote_jid; } catch(e) { remote_jid = json.remote_jid || 'sem-id'; }
let bodyContent = markdown;
if (typeof bodyContent === 'string') {
  bodyContent = bodyContent
    .replace(/^###\s+(.*$)/gm, '<h4 class="text-base font-semibold text-slate-700 mt-6 mb-2">$1</h4>')
    .replace(/^##\s+(.*$)/gm, '<h3 class="text-lg font-semibold text-blue-700 mt-8 mb-3">$1</h3>')
    .replace(/^#\s+(.*$)/gm, '<h2 class="text-xl font-bold text-blue-900 border-b border-blue-100 pb-2 mb-4 mt-10">$1</h2>')
    .replace(/\*\*(.*?)\*\*/g, '<strong class="font-semibold text-slate-900">$1</strong>')
    .replace(/^\s*-\s+(.*$)/gm, '<li>$1</li>')
    .replace(/(<li>.*<\/li>)/gs, '<ul class="list-disc ml-6 mb-4">$1</ul>')
    .replace(/⚠️/g, '<span class="text-red-600 font-semibold">⚠️</span>')
    .replace(/\n/g, '<br>');
}
const fullHtml = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><title>Resumo - ${remote_jid}</title><meta name="viewport" content="width=device-width,initial-scale=1.0"><script src="https://cdn.tailwindcss.com"></script><style>body{font-family:'Inter',system-ui,sans-serif;-webkit-font-smoothing:antialiased}</style></head><body class="bg-slate-50 min-h-screen py-10 px-4"><div class="max-w-4xl mx-auto bg-white shadow-xl rounded-xl overflow-hidden border border-slate-100"><div class="bg-slate-900 px-8 py-6 text-white flex justify-between items-center"><div><h1 class="text-2xl font-bold">Resumo Jurídico do Caso</h1><p class="text-slate-400 text-sm mt-1">Triagem Automatizada</p></div><div class="text-right hidden sm:block"><div class="text-xs font-mono bg-slate-800 px-3 py-1 rounded text-slate-300 mb-1">ID: ${remote_jid}</div><div class="text-xs text-slate-400">${new Date().toLocaleDateString('pt-BR')} às ${new Date().toLocaleTimeString('pt-BR')}</div></div></div><div class="p-8 prose prose-slate max-w-none text-slate-700 leading-relaxed">${bodyContent}</div><div class="bg-slate-50 px-8 py-4 border-t border-slate-100 text-center"><p class="text-xs text-slate-400 uppercase tracking-wider font-semibold">Documento Gerado por IA</p></div></div></body></html>`;
const fileName = `resumo_${remote_jid}_${Date.now()}.html`;
return { json: { html: fullHtml, fileName, remote_jid }, binary: { data: { data: Buffer.from(fullHtml).toString('base64'), mimeType: 'text/html', fileName } } };

const fileName = $('Converte para HTML').first().json.fileName;
const publicUrl = `https://api.zapcompany.com.br/storage/v1/object/public/whatsapp-media/${fileName}`;
return { url_resumo: publicUrl, remote_jid: $('Converte para HTML').first().json.remote_jid };

items.sort((a, b) => new Date(a.json.created_at) - new Date(b.json.created_at));
const saida = [];
const audioRegex = /\.(m4a|mp3|ogg|opus|wav|webm|aac)$/i;
const imageRegex = /\.(jpg|jpeg|png|gif|webp)$/i;
const documentRegex = /\.(pdf)$/i;
for (const item of items) {
  const j = item.json;
  const mediaUrl = j.media_url || null;
  const message = (j.message || '').trim();
  let processed_type = 'texto';
  let processed_content = message || '[TEXTO SEM CONTEÚDO]';
  if (mediaUrl) {
    if (audioRegex.test(mediaUrl)) { processed_type = 'audio'; processed_content = '[AUDIO]'; }
    else if (imageRegex.test(mediaUrl)) { processed_type = 'imagem'; processed_content = '[IMAGEM]'; }
    else if (documentRegex.test(mediaUrl)) { processed_type = 'documento'; processed_content = '[DOCUMENTO PDF]'; }
    else { processed_type = 'arquivo'; processed_content = '[ARQUIVO NÃO CLASSIFICADO]'; }
  }
  saida.push({ json: { processed_type, processed_content, media_url: mediaUrl, created_at: j.created_at, remote_jid: j.remote_jid, from_me: j.from_me } });
}
return saida;

items.sort((a,b)=> new Date(a.json.created_at) - new Date(b.json.created_at));
const history = items.map(i => `[${i.json.role_label}]: ${i.json.processed_content}`).join('\n\n');
return { json: { history, remote_jid: items[0]?.json.remote_jid || 'desconhecido' } };

const json = $input.item.json;
const visionText = json.output || json.text || json.message?.content || json.content || json.response || json.data || json.result || '⚠️ análise indisponível.';
const finalText = typeof visionText === 'string' ? visionText.trim() : JSON.stringify(visionText);
return { json: { processed_type: 'imagem', processed_content: `📎 Análise da Imagem:\n${finalText}`, media_url: json.media_url || null, created_at: json.created_at || new Date().toISOString(), remote_jid: json.remote_jid || 'sem-id', from_me: json.from_me || false } };

// Parseia dados do cliente da Etapa 1
const json = $input.item.json;
const raw = json.output || json.text || json.message?.content || json.content || json.response || json.data || '';
const rawStr = typeof raw === 'string' ? raw : JSON.stringify(raw);

let dadosCliente = {};
try {
  const parsed = JSON.parse(rawStr);
  dadosCliente = parsed.dados_cliente || parsed;
} catch (e) {
  const jsonMatch = rawStr.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try { const parsed = JSON.parse(jsonMatch[0]); dadosCliente = parsed.dados_cliente || parsed; } catch(e2) {}
  }
}

const webhook = $('Webhook Resumo').first().json.body;
const history = $('Consolida Histórico1').first().json.history;
const remote_jid = $('Consolida Histórico1').first().json.remote_jid;

return {
  json: {
    dadosCliente,
    history,
    remote_jid,
    contract_content: webhook.contract_content || '',
    contract_file_url: webhook.contract_file_url || '',
    contract_name: webhook.contract_name || 'Contrato',
    variables_needed: webhook.variables_needed || [],
    briefing_context: webhook.briefing_context || ''
  }
};

// ============================================
// CONTRATO TEXTO: Substituição direta de {{variáveis}}
// Preserva o layout EXATO do modelo original
// ============================================
const data = $input.item.json;
const dadosCliente = data.dadosCliente || {};
const contractContent = data.contract_content || '';
const contractName = data.contract_name || 'Contrato';
const remote_jid = data.remote_jid || 'desconhecido';

// Copia o template original
let filledContract = contractContent;

// Substitui cada {{variável}} pelo valor encontrado
for (const [key, value] of Object.entries(dadosCliente)) {
  if (value && typeof value === 'string' && value.trim()) {
    // Regex flexível: aceita espaços dentro de {{ }}
    const regex = new RegExp(`\\{\\{\\s*${key.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\$&')}\\s*\\}\\}`, 'gi');
    filledContract = filledContract.replace(regex, value.trim());
  }
}

// Marca variáveis que NÃO foram preenchidas
filledContract = filledContract.replace(/\{\{\s*([^}]+?)\s*\}\}/g, '[A PREENCHER: $1]');

return {
  json: {
    variables: dadosCliente,
    filledContract,
    contractName,
    remote_jid,
    isTextContract: true
  }
};

// ============================================
// Monta prompt para CONTRATO ARQUIVO
// A IA recebe o modelo extraído + dados do cliente
// e deve preencher o contrato MANTENDO O LAYOUT ORIGINAL
// ============================================
const rawText = $input.item.json;
let contractText = '';
if (typeof rawText.text === 'string') contractText = rawText.text;
else if (Array.isArray(rawText.text)) contractText = rawText.text.join('\n');
else if (rawText.text) contractText = JSON.stringify(rawText.text);
contractText = (contractText || '').trim();
if (!contractText || contractText.length < 20) contractText = '(Não foi possível extrair texto do arquivo)';
if (contractText.length > 15000) contractText = contractText.slice(0, 15000) + '\n[TRUNCADO]';

const etapa1 = $('Parseia Dados Cliente').first().json;
const dadosCliente = etapa1.dadosCliente;
const contractName = etapa1.contract_name;
const briefing = etapa1.briefing_context;
const remote_jid = etapa1.remote_jid;
const history = etapa1.history;

const dadosStr = Object.entries(dadosCliente)
  .filter(([k, v]) => v && v.trim())
  .map(([k, v]) => `- ${k}: ${v}`)
  .join('\n');

const systemPrompt = `Você é um assistente jurídico especializado em preencher contratos.

REGRA FUNDAMENTAL: Você DEVE manter o texto do contrato EXATAMENTE como está no modelo original.
NÃO reescreva, NÃO resuma, NÃO altere a ordem, NÃO mude a formatação.
APENAS substitua os campos em branco/variáveis pelos dados do cliente.

Você receberá:
1. O TEXTO DO MODELO DO CONTRATO (extraído do arquivo original)
2. Os DADOS DO CLIENTE já extraídos da conversa
3. O HISTÓRICO DA CONVERSA (para buscar dados adicionais)

Sua tarefa:
- Copie o contrato INTEIRO, palavra por palavra
- Onde houver campos a preencher (espaços em branco, underlines ___, marcadores, etc.), substitua pelos dados do cliente
- Onde não tiver dado disponível, coloque [A PREENCHER]
- MANTENHA toda a estrutura: parágrafos, cláusulas, numeração, espaçamento

RESPONDA com JSON:
{
  "variables": {"campo": "valor", ...},
  "filled_contract": "O contrato COMPLETO preservando o layout original, com os dados preenchidos"
}`;

const userPrompt = `## MODELO DO CONTRATO: ${contractName}\n\n${contractText}\n\n## DADOS DO CLIENTE:\n${dadosStr || 'Nenhum.'}\n\n## BRIEFING:\n${briefing || 'Nenhum.'}\n\n## HISTÓRICO:\n${history}`;

return {
  json: { systemPrompt, userPrompt, contractName, remote_jid, dadosCliente }
};

// Parseia resposta da Etapa 2 (contrato arquivo)
const json = $input.item.json;
const raw = json.output || json.text || json.message?.content || json.content || json.response || json.data || '';
const rawStr = typeof raw === 'string' ? raw : JSON.stringify(raw);

let variables = {};
let filledContract = '';

try {
  const parsed = JSON.parse(rawStr);
  variables = parsed.variables || {};
  filledContract = parsed.filled_contract || '';
} catch (e) {
  const jsonMatch = rawStr.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try { const parsed = JSON.parse(jsonMatch[0]); variables = parsed.variables || {}; filledContract = parsed.filled_contract || ''; } catch(e2) { filledContract = rawStr; }
  } else { filledContract = rawStr; }
}

// Mescla dados do cliente
let dadosCliente = {};
try { dadosCliente = $('Parseia Dados Cliente').first().json.dadosCliente || {}; } catch(e) {}
const mergedVars = { ...dadosCliente, ...variables };

return {
  json: {
    variables: mergedVars,
    filledContract,
    remote_jid: $('Parseia Dados Cliente').first().json.remote_jid || 'desconhecido',
    contractName: $('Parseia Dados Cliente').first().json.contract_name || 'Contrato',
    isTextContract: false
  }
};

// ============================================
// GERA HTML DO CONTRATO PRESERVANDO LAYOUT ORIGINAL
// Usa fonte serifada (Times) e formatação de contrato real
// ============================================
const json = $input.item.json;
const filledContract = json.filledContract || '';
const variables = json.variables || {};
const remote_jid = json.remote_jid || 'desconhecido';
const contractName = json.contractName || 'Contrato';

// Converter texto para HTML preservando layout
let contractHtml = filledContract;
if (typeof contractHtml === 'string') {
  // Escapar HTML
  contractHtml = contractHtml
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  // Destacar campos não preenchidos
  contractHtml = contractHtml.replace(
    /\[A PREENCHER(:[^\]]*)?\]/g,
    '<mark style="background:#FEF08A;padding:2px 6px;border-radius:3px;font-weight:600;">$&</mark>'
  );

  // Preservar formatação: converter quebras de linha
  // Parágrafos duplos
  contractHtml = contractHtml.replace(/\n\n/g, '</p><p style="margin:0 0 12px 0;text-align:justify;text-indent:40px;">');
  // Quebras simples
  contractHtml = contractHtml.replace(/\n/g, '<br>');

  // Envolver em parágrafo
  contractHtml = '<p style="margin:0 0 12px 0;text-align:justify;text-indent:40px;">' + contractHtml + '</p>';
}

// Tabela de dados extraídos
let varsTable = '';
const varKeys = Object.keys(variables).filter(k => !k.startsWith('_') && variables[k] && variables[k].trim());
if (varKeys.length > 0) {
  const rows = varKeys.map(k => {
    return `<tr><td style="border:1px solid #ddd;padding:6px 12px;font-weight:500;">${k}</td><td style="border:1px solid #ddd;padding:6px 12px;">${variables[k]}</td></tr>`;
  }).join('');
  varsTable = `
    <div style="margin:20px 0 30px 0;page-break-inside:avoid;">
      <h3 style="font-size:14px;font-weight:bold;margin-bottom:10px;color:#1e40af;">Dados Extraídos da Conversa</h3>
      <table style="width:100%;border-collapse:collapse;font-size:12px;font-family:'Inter',Arial,sans-serif;">
        <thead><tr style="background:#f1f5f9;"><th style="border:1px solid #ddd;padding:6px 12px;text-align:left;">Campo</th><th style="border:1px solid #ddd;padding:6px 12px;text-align:left;">Valor</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;
}

const fullHtml = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <title>${contractName}</title>
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    @page { margin: 2cm 2.5cm; }
    body {
      font-family: 'Times New Roman', 'Georgia', serif;
      font-size: 12pt;
      line-height: 1.8;
      color: #1a1a1a;
      background: #f8fafc;
      margin: 0;
      padding: 40px 20px;
    }
    .contract-page {
      max-width: 210mm;
      margin: 0 auto;
      background: white;
      padding: 60px 70px;
      box-shadow: 0 4px 24px rgba(0,0,0,0.1);
      border: 1px solid #e2e8f0;
      min-height: 297mm;
    }
    .contract-header {
      text-align: center;
      margin-bottom: 40px;
      border-bottom: 2px solid #1a1a1a;
      padding-bottom: 20px;
    }
    .contract-header h1 {
      font-size: 16pt;
      font-weight: bold;
      text-transform: uppercase;
      letter-spacing: 2px;
      margin: 0 0 8px 0;
    }
    .contract-body {
      text-align: justify;
    }
    .contract-footer {
      margin-top: 60px;
      text-align: center;
      font-size: 10pt;
      color: #666;
      border-top: 1px solid #ccc;
      padding-top: 20px;
    }
    .signature-area {
      margin-top: 80px;
      display: flex;
      justify-content: space-between;
    }
    .signature-line {
      width: 45%;
      text-align: center;
    }
    .signature-line hr {
      border: none;
      border-top: 1px solid #1a1a1a;
      margin-bottom: 8px;
    }
    @media print {
      body { background: white; padding: 0; }
      .contract-page { box-shadow: none; border: none; padding: 0; }
    }
  </style>
</head>
<body>
  <div class="contract-page">
    <div class="contract-header">
      <h1>${contractName}</h1>
    </div>
    ${varsTable}
    <div class="contract-body">
      ${contractHtml}
    </div>
    <div class="signature-area">
      <div class="signature-line">
        <hr>
        <p style="font-size:10pt;">Contratante</p>
      </div>
      <div class="signature-line">
        <hr>
        <p style="font-size:10pt;">Contratado(a)</p>
      </div>
    </div>
    <div class="contract-footer">
      <p>Documento gerado por IA em ${new Date().toLocaleDateString('pt-BR')} — Requer revisão humana</p>
    </div>
  </div>
</body>
</html>`;

const fileName = `contrato_${remote_jid}_${Date.now()}.html`;

return {
  json: { html: fullHtml, fileName, remote_jid, variables },
  binary: {
    data: {
      data: Buffer.from(fullHtml).toString('base64'),
      mimeType: 'text/html',
      fileName
    }
  }
};

const fileName = $('Gera HTML Contrato').first().json.fileName;
const publicUrl = `https://api.zapcompany.com.br/storage/v1/object/public/whatsapp-media/${fileName}`;
return { json: { url_contrato: publicUrl, remote_jid: $('Gera HTML Contrato').first().json.remote_jid, variables: $('Gera HTML Contrato').first().json.variables } };
